function WebRosterScore(row){
  const score=Number(row.participation?.score||0)+Number(row.points||0);
  return Number.isFinite(score)?score:0;
}
function WebRosterRanks(rows){
  const sorted=rows.filter(row=>row.participation).slice().sort((a,b)=>WebRosterScore(b)-WebRosterScore(a));
  const ranks=new Map();let previous=null,rank=0;
  sorted.forEach((row,index)=>{const score=WebRosterScore(row);if(previous===null||score!==previous)rank=index+1;ranks.set(row.key,rank);previous=score;});
  return ranks;
}
