function WebParseJoin(raw){
  const input=String(raw||'').trim();
  if(/^[A-Z2-9]{6}$/i.test(input))return input.toUpperCase();
  const url=new URL(input,window.location.href);
  if(!['https:','http:'].includes(url.protocol))throw new Error('請掃描講師提供的場次 QR Code。');
  const match=url.hash.match(/^#\/join\/([A-Za-z2-9]{6})(?:\?(.*))?$/);
  if(!match)throw new Error('這不是有效的課堂加入 QR Code。');
  const params=new URLSearchParams(match[2]||'');
  if((params.has('p')&&params.get('p')!==qp?.ref)||(params.has('k')&&params.get('k')!==qp?.key))throw new Error('此 QR Code 屬於另一個教學專案，請使用目前講師提供的 QR Code。');
  return match[1].toUpperCase();
}
